name: 重复 Issue 检测 / Detect Duplicate Issues

on:
  issues:
    types: [opened]

permissions:
  contents: read
  issues: write

jobs:
  dedup:
    name: 关闭重复 Issue / Close duplicate issues
    runs-on: ubuntu-latest

    steps:
      - name: 检测重复 Issue / Detect duplicate issue
        uses: actions/github-script@v8
        with:
          script: |
            const issue = context.payload.issue;
            if (!issue || issue.pull_request) {
              return;
            }

            const title = (issue.title || '').trim();
            if (title.length < 4) {
              return;
            }

            const STOPWORDS = new Set([
              'the', 'a', 'an', 'is', 'are', 'of', 'to', 'in', 'on', 'for', 'and', 'or',
              'bug', 'issue',
            ]);
            const tokens = (title.match(/[\p{L}\p{N}]+/gu) || [])
              .filter((token) => !STOPWORDS.has(token.toLowerCase()));
            const sanitize = (value) =>
              value.replace(/[^\p{L}\p{N}\s]/gu, ' ').replace(/\s+/g, ' ').trim();
            const query = sanitize(tokens.length > 0 ? tokens.slice(0, 8).join(' ') : title);
            if (!query) {
              return;
            }

            const { data: search } = await github.rest.search.issuesAndPullRequests({
              q: 'repo:' + context.repo.owner + '/' + context.repo.repo +
                ' is:issue is:open in:title ' + query,
              per_page: 30,
            });
            const candidates = (search.items || []).filter(
              (item) => item.number !== issue.number && !item.pull_request,
            );

            const levenshtein = (left, right) => {
              const rows = left.length;
              const columns = right.length;
              if (rows === 0) return columns;
              if (columns === 0) return rows;
              const distance = new Array(columns + 1);
              for (let column = 0; column <= columns; column += 1) distance[column] = column;
              for (let row = 1; row <= rows; row += 1) {
                let previous = distance[0];
                distance[0] = row;
                for (let column = 1; column <= columns; column += 1) {
                  const current = distance[column];
                  distance[column] = Math.min(
                    distance[column] + 1,
                    distance[column - 1] + 1,
                    previous + (left[row - 1] === right[column - 1] ? 0 : 1),
                  );
                  previous = current;
                }
              }
              return distance[columns];
            };
            const normalize = (value) => value.replace(/\s+/g, ' ').trim().toLowerCase();
            const similarity = (left, right) => {
              const maxLength = Math.max(left.length, right.length);
              return maxLength === 0 ? 1 : 1 - levenshtein(left, right) / maxLength;
            };

            const target = normalize(title);
            const duplicate = candidates.find((candidate) => {
              const candidateTitle = normalize(candidate.title);
              const contained =
                (target.includes(candidateTitle) || candidateTitle.includes(target)) &&
                Math.abs(target.length - candidateTitle.length) <=
                  Math.max(4, Math.min(target.length, candidateTitle.length) * 0.3);
              return contained || similarity(target, candidateTitle) >= 0.7;
            });
            if (!duplicate) {
              return;
            }

            const comment = [
              '该 Issue 疑似与已有 Issue 重复，已自动关闭。',
              'This issue appears to duplicate an existing issue and was closed automatically.',
              '',
              `- 原 Issue / Existing issue: #${duplicate.number}「${duplicate.title}」`,
              `- 链接 / Link: ${duplicate.html_url}`,
              '',
              '如果现象、版本或根因不同，请回复说明差异并请求重开；也可以到原 Issue 下补充新证据。',
              'If the behavior, version, or root cause differs, reply with those differences and request reopening, or add the new evidence to the existing issue.',
            ].join('\n');
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: issue.number,
              body: comment,
            });
            try {
              await github.rest.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issue.number,
                labels: ['duplicate'],
              });
            } catch (error) {
              core.warning(`Could not add duplicate label: ${error.message}`);
            }
            await github.rest.issues.update({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: issue.number,
              state: 'closed',
              state_reason: 'not_planned',
            });

name: Issue 信息检查 / Check Issue Information

on:
  issues:
    types: [opened, reopened, edited]

concurrency:
  group: issue-template-check-${{ github.event.issue.number }}
  cancel-in-progress: false

permissions:
  contents: read
  issues: write

jobs:
  enforce:
    name: 提示缺失的 Issue 信息 / Request missing issue information
    runs-on: ubuntu-latest

    steps:
      - name: 校验 Issue 模板 / Validate issue template
        uses: actions/github-script@v8
        with:
          script: |
            const eventIssue = context.payload.issue;
            if (!eventIssue || eventIssue.pull_request) {
              return;
            }

            const issueParams = {
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: eventIssue.number,
            };
            const escapeRegExp = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const readSection = (body, label) => {
              const heading = escapeRegExp(label);
              const pattern = new RegExp(`(?:^|\\n)###\\s+${heading}\\s*\\n+([\\s\\S]*?)(?=\\n###\\s+|$)`, 'i');
              const match = body.match(pattern);
              return match ? match[1].replace(/<!--[\s\S]*?-->/g, '').trim() : '';
            };

            const isBlank = (value) => {
              const normalized = value.replace(/\s+/g, ' ').trim().toLowerCase();
              return normalized === '' || normalized === 'no response' || normalized === '_no response_';
            };
            const hasCheckedBox = (value) => /^-\s*\[[xX]\]\s+\S+/m.test(value);
            const labels = {
              duplicate: '提交前查重 / Duplicate check',
              area: '涉及区域 / Affected area',
              type: 'Issue 类型 / Issue type',
              summary: '摘要 / Summary',
              expected: '预期结果 / Expected outcome',
              details: '详情或复现步骤 / Details or reproduction steps',
              environment: '环境信息 / Environment',
            };
            const requiredSections = [
              labels.duplicate,
              labels.area,
              labels.type,
              labels.summary,
              labels.expected,
              labels.details,
              labels.environment,
            ];
            const validateIssue = (issue) => {
              const section = (label) => readSection(issue.body || '', label);
              // Evidence is assessed by maintainers across the whole report.
              // Its section, code-block language and formatting are not gates.
              const missingSections = requiredSections.filter((label) => isBlank(section(label)));
              const invalidSections = [];
              if (!isBlank(section(labels.duplicate)) && !hasCheckedBox(section(labels.duplicate))) {
                invalidSections.push('请确认已经搜索过 open/closed Issue。 / Please confirm that you searched open and closed issues.');
              }

              return [
                ...(missingSections.length > 0 ? [`缺少或为空的必填部分 / Missing or empty required sections: ${missingSections.join(', ')}`] : []),
                ...invalidSections,
              ];
            };

            // The event payload is a snapshot. Read current state before acting,
            // including after comment lookup or adding a label.
            const { data: initialIssue } = await github.rest.issues.get(issueParams);
            if (initialIssue.state !== 'open') return;

            const marker = '<!-- dsh-mnemon:issue-template-check -->';
            const comments = await github.paginate(github.rest.issues.listComments, {
              ...issueParams,
              per_page: 100,
            });
            const previousComment = comments.find((comment) =>
              comment.user?.login === 'github-actions[bot]' &&
              comment.user?.type === 'Bot' &&
              comment.body?.startsWith(marker),
            );

            let { data: currentIssue } = await github.rest.issues.get(issueParams);
            if (currentIssue.state !== 'open') return;

            const issueType = readSection(currentIssue.body || '', labels.type).trim().toLowerCase();
            const hasBugLabel = (currentIssue.labels || []).some((label) => String(label.name || '').toLowerCase() === 'bug');
            if (issueType === 'bug 报告 / bug report' && !hasBugLabel) {
              // API/CLI reporters may not have permission to classify an issue.
              await github.rest.issues.addLabels({ ...issueParams, labels: ['bug'] });
              currentIssue = (await github.rest.issues.get(issueParams)).data;
              if (currentIssue.state !== 'open') return;
            }

            const details = validateIssue(currentIssue);
            if (details.length === 0 && !previousComment) return;

            const comment = details.length > 0 ? [
              marker,
              '此 Issue 保持打开。为便于排查，请补充以下基础信息：',
              'The issue remains open. Please add the following basic information to help triage:',
              '',
              ...details.map((detail) => `- ${detail}`),
              '',
              '在正文中补充即可，本提示会在编辑后更新。证据可以是普通文本、JSON 或其他代码块，也可以直接放在复现步骤中。',
              'Update the issue body and this reminder will refresh. Evidence may be plain text, JSON or other code blocks, including content in the reproduction steps.',
            ].join('\n') : [
              marker,
              '基础信息已补齐，后续由维护者排查和处理。',
              'Required report information is present. Maintainers will review the report.',
            ].join('\n');

            // Update only this check's own reminder. Never change issue state.
            if (previousComment) {
              if (previousComment.body !== comment) {
                await github.rest.issues.updateComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  comment_id: previousComment.id,
                  body: comment,
                });
              }
            } else {
              await github.rest.issues.createComment({ ...issueParams, body: comment });
            }

name: PR 贡献规范校验 / Enforce PR Contribution Rules

on:
  pull_request_target:
    types: [opened, edited, synchronize, reopened, ready_for_review]

permissions:
  contents: read
  pull-requests: read

jobs:
  enforce:
    name: 校验 PR 贡献信息 / Validate PR contribution evidence
    runs-on: ubuntu-latest
    if: ${{ !github.event.pull_request.draft }}

    steps:
      - name: 校验 PR 描述 / Validate pull request body
        uses: actions/github-script@v8
        with:
          script: |
            const pr = context.payload.pull_request;
            const body = pr.body || '';
            const escapeRegExp = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const readSection = (label) => {
              const heading = escapeRegExp(label);
              const pattern = new RegExp(`(?:^|\\n)##\\s+${heading}\\s*\\n+([\\s\\S]*?)(?=\\n##\\s+|$)`, 'i');
              const match = body.match(pattern);
              return match ? match[1].replace(/<!--[\s\S]*?-->/g, '').trim() : '';
            };
            const isBlank = (value) => {
              const normalized = value.replace(/\s+/g, ' ').trim().toLowerCase();
              return normalized === '' || normalized === 'no response' || normalized === '_no response_';
            };
            const checkedLines = (value) => value.match(/^-\s*\[[xX]\]\s+\S.*$/gm) || [];
            const hasCheckedLine = (value, label) => {
              const pattern = new RegExp(`^-\\s*\\[[xX]\\]\\s*${escapeRegExp(label)}\\s*$`, 'm');
              return pattern.test(value);
            };
            const cleanText = (value) => value
              .replace(/```[a-zA-Z0-9_-]*\s*/g, '')
              .replace(/```/g, '')
              .trim();
            const readLabeledPart = (value, label, nextLabel = null) => {
              const start = escapeRegExp(label);
              const end = nextLabel ? `\\n\\s*${escapeRegExp(nextLabel)}\\s*[：:]` : '$';
              const pattern = new RegExp(`${start}\\s*[：:]\\s*([\\s\\S]*?)(?=${end})`, 'i');
              const match = value.match(pattern);
              return match ? cleanText(match[1]) : '';
            };
            const hasEvidence = (value) => /!\[[^\]]*]\([^)]+\)/i.test(value)
              || /https?:\/\/\S*(?:github\.com\/user-attachments\/assets\/|github\.com\/[^)\s]+\/assets\/|githubusercontent\.com\/|[./][^)\s]+\.(?:png|jpe?g|gif|webp|mp4|mov|webm))(?:[?#]\S*)?/i.test(value);

            let isMaintainer = false;
            try {
              const { data } = await github.rest.repos.getCollaboratorPermissionLevel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                username: pr.user.login,
              });
              isMaintainer = ['admin', 'maintain', 'write'].includes(data.permission);
            } catch (error) {
              core.info(`Contributor permission lookup returned no write grant: ${error.message}`);
            }

            const sections = {
              summary: '摘要 / Summary',
              related: '关联 Issue 或背景 / Related Issue or Context',
              affected: '涉及区域 / Affected Areas',
              type: 'PR 类型 / PR Type',
              latest: '最新代码确认 / Latest Codebase Confirmation',
              ai: 'AI 编码披露 / AI Coding Disclosure',
              rules: '仓库规范检查 / Repository Rules',
              compatibility: '兼容性与数据安全 / Compatibility and Data Safety',
              validation: '本地验证 / Local Validation',
              evidence: '用户可见变更证据 / Local Feature Evidence',
            };
            const labels = {
              latestConfirmation: '我已基于最新 `main` 分支开发，或在提交前已 rebase 或合并最新 `main`。 / I developed from the latest `main`, or rebased or merged the latest `main` before submitting.',
              syncCommand: '同步命令 / Sync command',
              aiModel: '使用的 AI 模型 / AI model used',
              aiTool: '使用的编码 Agent 工具 / Coding Agent tool used',
              commands: '执行的命令 / Commands run',
              result: '结果摘要 / Result summary',
              userFacing: '面向用户的功能或行为变更 / User-facing feature or behavior change',
            };

            const summary = readSection(sections.summary);
            const related = readSection(sections.related);
            const affected = readSection(sections.affected);
            const prType = readSection(sections.type);
            const latest = readSection(sections.latest);
            const ai = readSection(sections.ai);
            const repoRules = readSection(sections.rules);
            const compatibility = readSection(sections.compatibility);
            const validation = readSection(sections.validation);
            const evidence = readSection(sections.evidence);

            const errors = [];
            const titlePattern = /^(feat|fix|chore|docs|test|refactor|perf|build|ci|revert)(\([^)]+\))?!?:\s+\S.+$/;
            if (!titlePattern.test((pr.title || '').trim())) {
              errors.push('PR 标题必须使用 Conventional Commits：`type(scope): subject`。 / The PR title must use Conventional Commits: `type(scope): subject`.');
            }
            if (isBlank(summary)) errors.push('请填写“摘要 / Summary”。 / Complete “摘要 / Summary”.');
            if (isBlank(related)) errors.push('请填写“关联 Issue 或背景 / Related Issue or Context”；没有 Issue 时填写 N/A 并解释。 / Complete “关联 Issue 或背景 / Related Issue or Context”; enter N/A with an explanation when no Issue exists.');
            if (checkedLines(affected).length === 0) errors.push('请在“涉及区域 / Affected Areas”中至少勾选一项。 / Check at least one item in “涉及区域 / Affected Areas”.');
            if (checkedLines(prType).length === 0) errors.push('请在“PR 类型 / PR Type”中至少勾选一项。 / Check at least one item in “PR 类型 / PR Type”.');

            if (!hasCheckedLine(latest, labels.latestConfirmation)) {
              errors.push('请确认本 PR 基于最新 `main`。 / Confirm that this PR is based on the latest `main`.');
            }
            if (isBlank(readLabeledPart(latest, labels.syncCommand))) {
              errors.push('请填写同步最新 `main` 时执行的命令。 / Provide the command used to synchronize with the latest `main`.');
            }

            if (checkedLines(ai).length !== 1) {
              errors.push('“AI 编码披露 / AI Coding Disclosure”必须且只能勾选一项。 / Check exactly one option in “AI 编码披露 / AI Coding Disclosure”.');
            }
            const aiModel = readLabeledPart(ai, labels.aiModel, labels.aiTool);
            const aiTool = readLabeledPart(ai, labels.aiTool);
            if (isBlank(aiModel) || isBlank(aiTool)) {
              errors.push('请填写使用的 AI 模型和编码 Agent 工具；未使用时两项均填 N/A。 / Provide the AI model and coding Agent tool; enter N/A in both fields when none were used.');
            }

            const requiredRuleCount = 7;
            if (checkedLines(repoRules).length < requiredRuleCount) {
              errors.push('请逐项确认“仓库规范检查 / Repository Rules”的全部七项。 / Confirm all seven items in “仓库规范检查 / Repository Rules”.');
            }
            if (isBlank(compatibility)) {
              errors.push('请填写“兼容性与数据安全 / Compatibility and Data Safety”；没有影响时填 N/A 并说明理由。 / Complete “兼容性与数据安全 / Compatibility and Data Safety”; enter N/A with a reason when there is no impact.');
            }

            const validationCommands = readLabeledPart(validation, labels.commands, labels.result);
            const validationSummary = readLabeledPart(validation, labels.result);
            if (isBlank(validationCommands) || isBlank(validationSummary)) {
              errors.push('请填写“本地验证 / Local Validation”中的执行命令与结果摘要。 / Provide commands and a result summary in “本地验证 / Local Validation”.');
            }

            const userFacing = hasCheckedLine(prType, labels.userFacing);
            if (userFacing && !isMaintainer && !hasEvidence(evidence)) {
              errors.push('外部贡献者提交用户可见变更时，必须附本地截图或短视频证据。 / External contributors must attach local screenshot or short-video evidence for user-facing changes.');
            }

            if (errors.length === 0) {
              return;
            }

            await core.summary
              .addHeading('PR contribution requirements')
              .addRaw('Update the PR description and keep the complete template.\n')
              .addList(errors)
              .addRaw('After correction, edit the PR description or push a commit to rerun this check.\n')
              .write();
            for (const error of errors) core.error(error);
            core.setFailed(errors.join('\n'));

name: 拒绝仅文档 PR / Reject Documentation-only PRs

on:
  pull_request_target:
    types: [opened, reopened, edited, ready_for_review]

permissions:
  contents: read
  issues: write
  pull-requests: write

jobs:
  reject:
    name: 关闭外部仅文档 PR / Close external documentation-only PRs
    runs-on: ubuntu-latest
    if: ${{ !github.event.pull_request.draft }}

    steps:
      - name: 自动关闭外部仅文档 PR / Auto-close external documentation-only PRs
        uses: actions/github-script@v8
        with:
          script: |
            const pr = context.payload.pull_request;
            const title = (pr.title || '').trim();
            if (!/^docs(?:\b|\s*\()/i.test(title)) {
              return;
            }

            let isMaintainer = false;
            try {
              const { data } = await github.rest.repos.getCollaboratorPermissionLevel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                username: pr.user.login,
              });
              isMaintainer = ['admin', 'maintain', 'write'].includes(data.permission);
            } catch (error) {
              core.info(`Contributor permission lookup returned no write grant: ${error.message}`);
            }
            if (isMaintainer) {
              core.info(`PR #${pr.number} is a maintainer documentation change; keeping it open.`);
              return;
            }

            const comment = [
              '本仓库不直接接受外部贡献者的仅文档类 PR，此 PR 已被自动关闭。',
              'This repository does not directly accept documentation-only PRs from external contributors, so this PR was closed automatically.',
              '',
              `请先到 https://github.com/${context.repo.owner}/${context.repo.repo}/issues 使用 Issue Form 说明需要修正的内容。 / Please use an Issue Form at https://github.com/${context.repo.owner}/${context.repo.repo}/issues to describe the requested documentation change first.`,
              '若本 PR 实际包含代码修复，请使用对应的 Conventional Commits 标题并按完整 PR 模板重新提交。',
              'If this PR contains a code fix, use the corresponding Conventional Commits title and resubmit with the complete PR template.',
            ].join('\n');
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: pr.number,
              body: comment,
            });
            await github.rest.issues.update({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: pr.number,
              state: 'closed',
              state_reason: 'not_planned',
            });
            core.setFailed(`PR #${pr.number} 是外部仅文档贡献，已自动关闭。 / PR #${pr.number} is an external documentation-only contribution and was closed automatically.`);

