name: Issue intake

on:
  issues:
    types: [opened, edited]

permissions:
  contents: read
  issues: write

jobs:
  intake:
    if: github.event.issue.user.type != 'Bot'
    runs-on: ubuntu-latest
    timeout-minutes: 3
    steps:
      - uses: actions/github-script@v8
        with:
          script: |
            const labelNames = new Set(
              (context.payload.issue.labels ?? []).map(label => typeof label === 'string' ? label : label.name),
            )
            const isBug = labelNames.has('bug')
            const isFeature = labelNames.has('enhancement')
            if (!isBug && !isFeature) return

            const comments = await github.paginate(github.rest.issues.listComments, {
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              per_page: 100,
            })
            const commentOnce = async (marker, body) => {
              if (comments.some(comment => comment.body?.includes(marker))) return
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                body: `${marker}\n${body}`,
              })
            }

            if (context.payload.action === 'opened' && isBug) {
              await commentOnce(
                '<!-- dsh-maintenance-ack -->',
                'Thanks for the report. We\'ll reproduce it on the reported plugin and DSH versions, then follow up here with what we find.\n\n感谢反馈。我们会按你提供的插件和 DSH 版本复现，并在这里同步核查结果。',
              )
            }

            if (context.payload.action === 'opened' && isFeature) {
              await commentOnce(
                '<!-- dsh-feature-ack -->',
                'Thanks for the suggestion. We\'ll first check whether DSH already provides this capability and whether it fits this plugin\'s scope, then follow up here.\n\n感谢建议。我们会先确认 DSH 是否已有对应能力，以及它是否适合由本插件负责，再在这里回复。',
              )
            }

            if (!isBug) return
            const body = context.payload.issue.body ?? ''
            const value = /^### Plugin version\s*\n+([^\n]+)/imu.exec(body)?.[1]?.trim()
            if (value?.toLowerCase() === 'not installed') return
            const version = /^v?\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?=\s|$)/u.exec(value ?? '')?.[0]
            if (!version) {
              await commentOnce(
                '<!-- dsh-version-check:missing -->',
                'Please edit the report and provide the exact plugin version from Settings or `dsh plugin --profile web list dsh-codex-subscription --depth 0`. If installation never completed, enter `not installed`.',
              )
              return
            }

            const response = await fetch('https://registry.npmjs.org/dsh-codex-subscription/latest')
            if (!response.ok) return
            const latest = String((await response.json()).version ?? '')
            const parts = version => version.replace(/^v/u, '').split(/[.-]/u).slice(0, 3).map(Number)
            const [major, minor, patch] = parts(version)
            const [latestMajor, latestMinor, latestPatch] = parts(latest)
            const older = major < latestMajor || (major === latestMajor && (minor < latestMinor || (minor === latestMinor && patch < latestPatch)))
            if (older) {
              await commentOnce(
                `<!-- dsh-version-check:outdated:${latest} -->`,
                `This report uses ${version}; the current release is ${latest}. Please update and say whether the problem still reproduces.`,
              )
            }

