name: Auto-assign issues to collaborator

on:
  issues:
    types: [opened]

permissions:
  contents: read
  issues: write

jobs:
  assign:
    name: Assign issue to collaborator
    runs-on: ubuntu-latest

    steps:
      - name: Assign every Issue to collaborator
        uses: actions/github-script@v8
        with:
          script: |
            const issue = context.payload.issue;
            if (!issue || issue.pull_request) {
              return;
            }

            // Issue ownership is independent from the PR routing configuration.
            const assignees = ['Aa728848'];
            await github.rest.issues.update({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: issue.number,
              assignees,
            });
            console.log(
              'Issue #' + issue.number + ': assigned ' + assignees.join(', ') + '.'
            );

name: Auto-assign PR reviewers

on:
  pull_request_target:
    types: [opened, reopened, synchronize, ready_for_review]

permissions:
  contents: read
  pull-requests: write

jobs:
  route:
    name: Route PR to category reviewers
    runs-on: ubuntu-latest
    if: ${{ !github.event.pull_request.draft }}

    steps:
      - name: Load routes and request reviewers
        uses: actions/github-script@v8
        with:
          script: |
            const pr = context.payload.pull_request;
            if (!pr) {
              return;
            }

            // 路由配置从 base 分支（可信代码）读取；PR 自身不能修改自己的路由。
            let routes;
            let defaultRoute = null;
            try {
              const config = await github.rest.repos.getContent({
                owner: context.repo.owner,
                repo: context.repo.repo,
                path: '.github/pr-review-routes.json',
                ref: pr.base.ref,
              });
              const parsed = JSON.parse(
                Buffer.from(config.data.content, 'base64').toString('utf8')
              );
              if (!Array.isArray(parsed.routes)) {
                throw new Error('routes must be an array');
              }
              routes = parsed.routes;
              defaultRoute = parsed.defaultRoute || null;
            } catch (error) {
              core.warning(
                'review routing config unavailable, skipping: ' +
                  String((error && error.message) || error)
              );
              return;
            }

            // 变更文件（分页收集，上限 300 个）。
            const files = [];
            for (let page = 1; page <= 3; page++) {
              const pageData = await github.rest.pulls.listFiles({
                owner: context.repo.owner,
                repo: context.repo.repo,
                pull_number: pr.number,
                per_page: 100,
                page,
              });
              files.push(...pageData.data.map((item) => item.filename));
              if (pageData.data.length < 100) {
                break;
              }
            }
            console.log('PR #' + pr.number + ': ' + files.length + ' changed files.');

            // PR 描述中勾选的类别（`## PR 类别（PR Category）` 小节）。
            const body = pr.body || '';
            const categoryPattern = /(?:^|\n)##\s+PR 类别（PR Category）\s*\n+([\s\S]*?)(?=\n##\s+|$)/i;
            const categoryMatch = body.match(categoryPattern);
            const selectedTypes = [];
            if (categoryMatch) {
              const section = categoryMatch[1].replace(/<!--[\s\S]*?-->/g, '');
              for (const line of section.split('\n')) {
                const m = line.match(/^-\s*\[[xX]\]\s*(.+)$/);
                if (m) {
                  selectedTypes.push(m[1].trim());
                }
              }
            }
            console.log(
              'PR #' + pr.number + ': selected categories: ' +
                (selectedTypes.join(', ') || 'none')
            );

            const globToRegExp = (pattern) => {
              // Escape the regex metacharacters, leaving * and ? for the glob tokens.
              const escaped = pattern.replace(/[.+^${}()|[\]\\]/g, '\\$&');
              const tokenized = escaped
                .replace(/\*\*/g, '\u0000')
                .replace(/\*/g, '[^/]*')
                .replace(/\?/g, '[^/]')
                .replace(/\u0000/g, '.*');
              return new RegExp('^' + tokenized + '$');
            };

            const matched = [];
            const seen = new Set();
            for (const route of routes) {
              if (seen.has(route.name)) {
                continue;
              }
              seen.add(route.name);
              const patterns = Array.isArray(route.paths) ? route.paths : [];
              const pathHit = patterns.some((pattern) => {
                const regexp = globToRegExp(pattern);
                return files.some((file) => regexp.test(file));
              });
              let titleHit = false;
              if (route.title) {
                try {
                  titleHit = new RegExp(route.title, 'i').test(pr.title || '');
                } catch (error) {
                  core.warning(
                    'invalid title regex for route ' + route.name + ': ' +
                      String((error && error.message) || error)
                  );
                }
              }
              const routeTypes = Array.isArray(route.types) ? route.types : [];
              const typeHit =
                routeTypes.length > 0 &&
                selectedTypes.some((type) => routeTypes.includes(type));
              const routeAuthors = Array.isArray(route.authors) ? route.authors : [];
              const authorHit = routeAuthors.includes(pr.user.login);
              if (pathHit || titleHit || typeHit || authorHit) {
                matched.push(route);
              }
            }

            if (matched.length === 0) {
              console.log('PR #' + pr.number + ': no review route matched.');
              // 兜底分配：确保每个 PR 都有人关联，不存在“无关联 PR”。
              if (defaultRoute) {
                const defaultReviewers = [...new Set(
                  (defaultRoute.reviewers || []).filter((user) => user !== pr.user.login)
                )];
                const defaultAssignees = [...new Set(
                  (defaultRoute.assignees || []).filter((user) => user !== pr.user.login)
                )];
                if (defaultReviewers.length > 0) {
                  await github.rest.pulls.requestReviewers({
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    pull_number: pr.number,
                    reviewers: defaultReviewers,
                  });
                  console.log(
                    'PR #' + pr.number + ': requested default reviewers ' + defaultReviewers.join(', ') + '.'
                  );
                }
                if (defaultAssignees.length > 0) {
                  await github.rest.issues.addAssignees({
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    issue_number: pr.number,
                    assignees: defaultAssignees,
                  });
                  console.log(
                    'PR #' + pr.number + ': assigned ' + defaultAssignees.join(', ') + '.'
                  );
                }
              }
              return;
            }

            const reviewers = [...new Set(
              matched.flatMap((route) => route.reviewers || [])
            )].filter((user) => user !== pr.user.login);

            const assignees = [...new Set(
              matched.flatMap((route) => route.assignees || [])
            )].filter((user) => user !== pr.user.login);

            if (reviewers.length > 0) {
              await github.rest.pulls.requestReviewers({
                owner: context.repo.owner,
                repo: context.repo.repo,
                pull_number: pr.number,
                reviewers,
              });
              console.log(
                'PR #' + pr.number + ': requested review from ' + reviewers.join(', ') + '.'
              );
            } else {
              console.log(
                'PR #' + pr.number + ': matched ' +
                  matched.map((route) => route.name).join(', ') +
                  ' but no reviewer to request.'
              );
            }

            if (assignees.length > 0) {
              await github.rest.issues.addAssignees({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: pr.number,
                assignees,
              });
              console.log(
                'PR #' + pr.number + ': assigned ' + assignees.join(', ') + '.'
              );
            }

            if (context.payload.action !== 'opened') {
              return;
            }

            const lines = matched.map(
              (route) => '- ' + route.name + (route.label ? '（' + route.label + '）' : '')
            );
            const summary = [];
            if (assignees.length > 0) {
              summary.push('已将 ' + assignees.join('、') + ' 设为负责人。');
            }
            if (reviewers.length > 0) {
              summary.push('已请求 ' + reviewers.join('、') + ' 审查。');
            }
            const comment = [
              '本 PR 已按类别自动路由：',
              '',
              ...lines,
              '',
              summary.join('') + '路由规则见 `.github/pr-review-routes.json`。',
            ].join('\n');
            try {
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: pr.number,
                body: comment,
              });
            } catch (error) {
              core.warning(
                'failed to post routing comment: ' + String((error && error.message) || error)
              );
            }

name: Auto-label issues

on:
  issues:
    types: [opened, edited]

permissions:
  contents: read
  issues: write

jobs:
  label:
    name: Apply labels based on issue fields
    runs-on: ubuntu-latest

    steps:
      - name: Parse issue template and add labels
        uses: actions/github-script@v8
        with:
          script: |
            const issue = context.payload.issue;
            if (!issue || issue.pull_request) {
              return;
            }

            const body = issue.body || '';
            const escapeRegExp = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const readSection = (label) => {
              const heading = escapeRegExp(label);
              const pattern = new RegExp(`(?:^|\\n)###\\s+${heading}\\s*\\n+([\\s\\S]*?)(?=\\n###\\s+|$)`, 'i');
              const match = body.match(pattern);
              return match ? match[1].replace(/<!--[\s\S]*?-->/g, '').trim() : '';
            };

            const pluginField = readSection('涉及插件').toLowerCase();
            const issueTypeField = readSection('Issue 类型').toLowerCase();

            const labelsToAdd = new Set();

            // 1. Issue type mapping
            if (issueTypeField.includes('bug') || issueTypeField.includes('缺陷')) {
              labelsToAdd.add('bug');
            } else if (issueTypeField.includes('功能') || issueTypeField.includes('feature') || issueTypeField.includes('request')) {
              labelsToAdd.add('enhancement');
            } else if (issueTypeField.includes('文档') || issueTypeField.includes('doc')) {
              labelsToAdd.add('documentation');
            } else if (issueTypeField.includes('问题') || issueTypeField.includes('question')) {
              labelsToAdd.add('question');
            }

            // 2. Plugin / Area mapping
            if (pluginField.includes('skin') || pluginField.includes('皮肤') || pluginField.includes('壁纸') || pluginField.includes('渲染器') || pluginField.includes('wallpaper')) {
              labelsToAdd.add('area/skins');
            }
            if (pluginField.includes('market') || pluginField.includes('工坊') || pluginField.includes('市场') || pluginField.includes('store') || pluginField.includes('workshop')) {
              labelsToAdd.add('area/market');
            }
            if (pluginField.includes('pet') || pluginField.includes('宠物')) {
              labelsToAdd.add('area/pet');
            }
            if (pluginField.includes('i18n') || pluginField.includes('国际化') || pluginField.includes('语言') || pluginField.includes('翻译')) {
              labelsToAdd.add('area/i18n');
            }
            if (pluginField.includes('perf') || pluginField.includes('性能')) {
              labelsToAdd.add('area/perf');
            }
            if (pluginField.includes('setting') || pluginField.includes('设置')) {
              labelsToAdd.add('area/settings');
            }
            if (pluginField.includes('session') || pluginField.includes('会话')) {
              labelsToAdd.add('area/session');
            }
            if (pluginField.includes('skill') || pluginField.includes('技能')) {
              labelsToAdd.add('area/skills');
            }
            if (pluginField.includes('image') || pluginField.includes('describe') || pluginField.includes('tool')) {
              labelsToAdd.add('area/tools');
            }
            if (pluginField.includes('remote') || pluginField.includes('远程') || pluginField.includes('web')) {
              labelsToAdd.add('area/web');
            }
            if (pluginField.includes('all') || pluginField.includes('聚合包') || pluginField.includes('安装') || pluginField.includes('ci') || pluginField.includes('build')) {
              labelsToAdd.add('area/infra');
            }
            if (
              pluginField.includes('task-board') ||
              pluginField.includes('git-graph') ||
              pluginField.includes('aionui') ||
              pluginField.includes('ssh') ||
              pluginField.includes('doctor') ||
              pluginField.includes('usage') ||
              pluginField.includes('liangshen') ||
              pluginField.includes('launcher') ||
              pluginField.includes('plugin-manager') ||
              pluginField.includes('community')
            ) {
              labelsToAdd.add('area/plugin');
            }

            // Filter out labels already present on the issue
            const currentLabels = new Set((issue.labels || []).map((l) => (typeof l === 'string' ? l : l.name)));
            const newLabels = Array.from(labelsToAdd).filter((l) => !currentLabels.has(l));

            if (newLabels.length > 0) {
              await github.rest.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issue.number,
                labels: newLabels,
              });
              console.log(`Issue #${issue.number}: added labels [${newLabels.join(', ')}]`);
            } else {
              console.log(`Issue #${issue.number}: no new labels to add.`);
            }

name: Detect Duplicate Issues

on:
  issues:
    types: [opened]

permissions:
  contents: read
  issues: write

jobs:
  dedup:
    name: Close duplicate issues
    runs-on: ubuntu-latest

    steps:
      - name: Detect duplicate issue
        uses: actions/github-script@v8
        with:
          script: |
            const issue = context.payload.issue;
            if (!issue || issue.pull_request) {
              return;
            }

            const title = (issue.title || '').trim();
            if (title.length < 4) {
              return;
            }

            const STOPWORDS = new Set([
              'the', 'a', 'an', 'is', 'are', 'of', 'to', 'in', 'on', 'for', 'and', 'or',
            ]);

            const tokens = (title.match(/[\p{L}\p{N}]+/gu) || [])
              .filter((t) => !STOPWORDS.has(t.toLowerCase()));

            const sanitize = (value) =>
              value.replace(/[^\p{L}\p{N}\s]/gu, ' ').replace(/\s+/g, ' ').trim();

            const query = sanitize(tokens.length > 0 ? tokens.slice(0, 8).join(' ') : title);
            if (!query) {
              return;
            }

            const { data: search } = await github.rest.search.issuesAndPullRequests({
              q: 'repo:' + context.repo.owner + '/' + context.repo.repo +
                ' is:issue is:open in:title ' + query,
              per_page: 30,
            });

            const candidates = (search.items || []).filter(
              (item) => item.number !== issue.number && !item.pull_request,
            );

            const levenshtein = (a, b) => {
              const m = a.length;
              const n = b.length;
              if (m === 0) return n;
              if (n === 0) return m;
              const dp = new Array(n + 1);
              for (let j = 0; j <= n; j += 1) dp[j] = j;
              for (let i = 1; i <= m; i += 1) {
                let prev = dp[0];
                dp[0] = i;
                for (let j = 1; j <= n; j += 1) {
                  const tmp = dp[j];
                  dp[j] = Math.min(
                    dp[j] + 1,
                    dp[j - 1] + 1,
                    prev + (a[i - 1] === b[j - 1] ? 0 : 1),
                  );
                  prev = tmp;
                }
              }
              return dp[n];
            };

            const normalize = (value) => value.replace(/\s+/g, ' ').trim().toLowerCase();
            const similarity = (a, b) => {
              const maxLen = Math.max(a.length, b.length);
              if (maxLen === 0) return 1;
              return 1 - levenshtein(a, b) / maxLen;
            };

            const target = normalize(title);
            const SIM_THRESHOLD = 0.7;

            const duplicate = candidates.find((candidate) => {
              const ct = normalize(candidate.title);
              const contained =
                (target.includes(ct) || ct.includes(target)) &&
                Math.abs(target.length - ct.length) <=
                  Math.max(4, Math.min(target.length, ct.length) * 0.3);
              return contained || similarity(target, ct) >= SIM_THRESHOLD;
            });

            if (!duplicate) {
              return;
            }

            const owner = context.repo.owner;
            const repo = context.repo.repo;

            const comment = [
              '该 Issue 疑似与已有 Issue 重复，已自动关闭。',
              '',
              '- 原 Issue：#' + duplicate.number + '「' + duplicate.title + '」',
              '- 链接：' + duplicate.html_url,
              '',
              '如果确认不是重复（现象不同、版本不同等），请回复说明差异，我们会重新打开；或直接到原 Issue 下补充信息。',
            ].join('\n');

            await github.rest.issues.createComment({
              owner,
              repo,
              issue_number: issue.number,
              body: comment,
            });

            try {
              await github.rest.issues.addLabels({
                owner,
                repo,
                issue_number: issue.number,
                labels: ['duplicate'],
              });
            } catch (error) {
              // `duplicate` label 可能不存在，忽略，不影响关闭。
            }

            await github.rest.issues.update({
              owner,
              repo,
              issue_number: issue.number,
              state: 'closed',
              state_reason: 'not_planned',
            });

name: Enforce Issue Template

on:
  issues:
    types: [opened, reopened]

permissions:
  contents: read
  issues: write

jobs:
  enforce:
    name: Close issues that skip the template
    runs-on: ubuntu-latest

    steps:
      - name: Validate issue template
        uses: actions/github-script@v8
        with:
          script: |
            const issue = context.payload.issue;
            if (issue.pull_request) {
              return;
            }

            const baseRequiredSections = [
              '涉及插件',
              'Issue 类型',
              '摘要',
              '预期结果',
              '详情 / 复现步骤',
              '环境信息',
            ];

            const body = issue.body || '';
            const escapeRegExp = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const readSection = (label) => {
              const heading = escapeRegExp(label);
              const pattern = new RegExp(`(?:^|\\n)###\\s+${heading}\\s*\\n+([\\s\\S]*?)(?=\\n###\\s+|$)`, 'i');
              const match = body.match(pattern);
              return match ? match[1].replace(/<!--[\s\S]*?-->/g, '').trim() : '';
            };

            const isBlank = (value) => {
              const normalized = value.replace(/\s+/g, ' ').trim().toLowerCase();
              return normalized === '' || normalized === 'no response' || normalized === '_no response_';
            };

            const hasScreenshotEvidence = (value) => {
              return /!\[[^\]]*]\([^)]+\)/i.test(value)
                || /https?:\/\/\S*(?:github\.com\/user-attachments\/assets\/|github\.com\/[^)\s]+\/assets\/|githubusercontent\.com\/|[./][^)\s]+\.(?:png|jpe?g|gif|webp))(?:[?#]\S*)?/i.test(value);
            };

            const issueType = readSection('Issue 类型').trim().toLowerCase();
            // Bug-ness is decided from the body alone. Labels are NOT an input:
            // the bug form's label is attached atomically by GitHub for form
            // submissions, but a report opened through the API or CLI gets its
            // labels from auto-label-issues.yml, which runs on its own
            // `issues: opened` event. This job also runs on `opened`, so the
            // two race and the label may legitimately be missing here — that is
            // why requiring it closed every non-collaborator bug report
            // (issues #1646 and #1648) before any human saw it.
            const isBug = issueType.includes('bug 报告') || issueType.includes('bug');
            const requiredSections = isBug
              ? [...baseRequiredSections, 'Bug 截图', '冒烟测试', '引用代码']
              : baseRequiredSections;

            const missingSections = requiredSections.filter((label) => isBlank(readSection(label)));
            const invalidSections = [];
            const bugScreenshot = readSection('Bug 截图');
            if (isBug && !isBlank(bugScreenshot) && !hasScreenshotEvidence(bugScreenshot)) {
              invalidSections.push('Bug 截图必须包含上传的图片、Markdown 图片或图片链接。');
            }
            const missingSectionMessages = missingSections.length > 0
              ? [`缺少或为空的必填部分：${missingSections.join(', ')}`]
              : [];

            if (missingSections.length === 0 && invalidSections.length === 0) {
              return;
            }

            const comment = [
              '该 Issue 因未使用仓库要求的 Issue 模板而被自动关闭。',
              '',
              '请从仓库的 Issue 表单重新发起，并填写所有必填部分：',
              '',
              ...requiredSections.map((label) => `- ${label}`),
              '',
              ...missingSectionMessages,
              ...invalidSections,
            ].join('\n');

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: issue.number,
              body: comment,
            });

            await github.rest.issues.update({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: issue.number,
              state: 'closed',
              state_reason: 'not_planned',
            });

name: Enforce PR Contribution Rules

on:
  pull_request_target:
    types: [opened, edited, synchronize, reopened, ready_for_review]

permissions:
  contents: read
  issues: write
  pull-requests: write

jobs:
  enforce:
    name: Validate PR contribution evidence
    runs-on: ubuntu-latest
    if: ${{ !github.event.pull_request.draft }}

    steps:
      - name: Validate pull request body
        uses: actions/github-script@v8
        with:
          script: |
            const pr = context.payload.pull_request;
            const body = pr.body || '';

            const escapeRegExp = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const readSection = (label) => {
              const heading = escapeRegExp(label);
              const pattern = new RegExp(`(?:^|\\n)##\\s+${heading}\\s*\\n+([\\s\\S]*?)(?=\\n##\\s+|$)`, 'i');
              const match = body.match(pattern);
              return match ? match[1].replace(/<!--[\s\S]*?-->/g, '').trim() : '';
            };

            const isBlank = (value) => {
              const normalized = value.replace(/\s+/g, ' ').trim().toLowerCase();
              return normalized === '' || normalized === 'no response' || normalized === '_no response_';
            };

            const hasCheckedLine = (value, label) => {
              const pattern = new RegExp(`^-\\s*\\[[xX]\\]\\s*${escapeRegExp(label)}\\s*$`, 'm');
              return pattern.test(value);
            };

            const hasAnyCheckedBox = (value) => /^-\s*\[[xX]\]\s+\S+/m.test(value);
            const cleanValidationText = (value) => value
              .replace(/```[a-zA-Z0-9_-]*\s*/g, '')
              .replace(/```/g, '')
              .trim();
            const readValidationPart = (value, label, nextLabel = null) => {
              const start = escapeRegExp(label);
              const end = nextLabel ? `\\n\\s*${escapeRegExp(nextLabel)}\\s*[：:]` : '$';
              const pattern = new RegExp(`${start}\\s*[：:]\\s*([\\s\\S]*?)(?=${end})`, 'i');
              const match = value.match(pattern);
              return match ? cleanValidationText(match[1]) : '';
            };
            const hasEvidence = (value) => {
              return /!\[[^\]]*]\([^)]+\)/i.test(value)
                || /https?:\/\/\S*(?:github\.com\/user-attachments\/assets\/|github\.com\/[^)\s]+\/assets\/|githubusercontent\.com\/|[./][^)\s]+\.(?:png|jpe?g|gif|webp|mp4|mov|webm))(?:[?#]\S*)?/i.test(value);
            };

            const prType = readSection('PR 类型（PR Type）');
            const prCategory = readSection('PR 类别（PR Category）');
            const latest = readSection('最新代码确认（Latest Codebase Confirmation）');
            const evidenceRules = readSection('测试证据与上游同步（Test Evidence & Upstream Sync）');
            const visualRules = readSection('视觉修复要求（Visual Fix Requirements）');
            const validation = readSection('本地验证（Local Validation）');
            const evidence = readSection('用户可见变更证据（Local Feature Evidence）');
            const ai = readSection('AI 编码披露（AI Coding Disclosure）');
            const aiUsed = hasCheckedLine(ai, '完全 AI 编码') || hasCheckedLine(ai, '部分 AI 辅助');
            const aiModelMatch = ai.match(/使用的 AI 模型[：:]\s*([^\n]+)/);
            const aiModel = aiModelMatch ? aiModelMatch[1].trim() : '';
            // 已知纯文本模型（不支持图像输入）：视觉修复类 PR 禁用。
            const textOnlyModel = [
              /^deepseek$/i,
              /deepseek[-_ ]?(chat|reasoner|r1|v3|v2|v1)/i,
              /gpt[-_ ]?3(\.5)?([-_ ]turbo)?/i,
              /llama[-_ ]?(2|3)/i,
              /glm[-_ ]?(3|4)/i,
              /moonshot|kimi/i,
              /doubao|豆包/i,
              /ernie|文心/i,
              /mistral/i,
            ];
            const visualFix = hasCheckedLine(prType, '视觉修复（UI / 视觉类问题的修复）');
            const userFacing = hasCheckedLine(prType, '面向用户的功能或行为变更');

            const errors = [];
            if (!hasAnyCheckedBox(prType)) {
              errors.push('请在 `PR 类型（PR Type）` 中至少勾选一项。');
            }
            if (!hasAnyCheckedBox(prCategory)) {
              errors.push('请在 `PR 类别（PR Category）` 中至少勾选一项。');
            }
            if (!hasCheckedLine(latest, '我已基于最新 `dev` 分支开发，或在提交前已 rebase / 合并最新 `dev`。')) {
              errors.push('请在 `最新代码确认（Latest Codebase Confirmation）` 中确认本 PR 基于最新 `dev` 分支。');
            }
            const validationCommands = readValidationPart(validation, '执行的命令', '结果摘要');
            const validationSummary = readValidationPart(validation, '结果摘要');
            if (isBlank(validationCommands) || isBlank(validationSummary)) {
              errors.push('请填写 `本地验证（Local Validation）` 中的执行的命令与结果摘要。');
            }

            // 证据门槛面向外部贡献者：自测证据 + 同步上游最新 dev 分支后
            // 重新测试通过的截图，缺一即拒绝；仓库所有者自审的 PR 由发布
            // 构建与自动化套件把关。
            const isRepoOwner = pr.user.login === context.repo.owner;
            const isBot = pr.user.login === 'github-actions[bot]';
            if (!isRepoOwner && !isBot) {
              if (!hasCheckedLine(evidenceRules, '我提供了自己本地测试的证据（执行的命令 / 测试结果 / 运行截图）。')) {
                errors.push('请在 `测试证据与上游同步（Test Evidence & Upstream Sync）` 中勾选「我提供了自己本地测试的证据」。');
              }
              if (!hasCheckedLine(evidenceRules, '我已同步上游最新 `dev` 分支（`git fetch origin && git rebase origin/dev`），并附上同步后重新测试通过的证据（视觉 / 用户可见变更附截图）。')) {
                errors.push('请在 `测试证据与上游同步（Test Evidence & Upstream Sync）` 中勾选上游同步项，并附上同步 `dev` 最新代码后重新测试通过的证据。');
              }
              if ((visualFix || userFacing) && !hasEvidence(evidence)) {
                errors.push('视觉修复 / 用户可见变更的 PR 必须附带截图或视频证据：视觉修复还需完成态或修复前后对比截图。');
              }
              if (visualFix) {
                if (!hasCheckedLine(visualRules, '我提供了修复完成后的截图（完成态或修复前后对比）。')) {
                  errors.push('请在 `视觉修复要求（Visual Fix Requirements）` 中勾选「我提供了修复完成后的截图」。');
                }
                if (aiUsed && !hasCheckedLine(visualRules, '修复使用的 AI 模型支持图像输入（多模态模型）；未使用 AI 编码时此项视为满足。')) {
                  errors.push('视觉修复必须使用支持图像输入的多模态 AI 模型完成；请在 `视觉修复要求` 中勾选并填写模型名。');
                }
                if (aiUsed && (aiModel === '' || textOnlyModel.some((re) => re.test(aiModel)))) {
                  errors.push('视觉修复使用的 AI 模型必须是多模态模型（支持图像输入）；纯文本模型（如 deepseek-chat / deepseek-reasoner / gpt-3.5）修复的视觉类 PR 不接受。');
                }
              }
            }

            if (errors.length === 0) {
              return;
            }

            const comment = [
              '本 PR 缺少必要的贡献信息。',
              '',
              '请更新 PR 描述并保持 PR 模板完整：',
              '',
              ...errors.map((error) => `- ${error}`),
              '',
              '贡献者 PR 必须附带本地测试证据：自测测试记录 + 同步上游最新 dev 分支后重新测试通过的证据；视觉修复需附完成截图（完成态或修复前后对比），且必须使用支持图像输入的多模态 AI 模型完成。',
            ].join('\n');

            if (context.payload.action !== 'synchronize') {
              try {
                await github.rest.issues.createComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: pr.number,
                  body: comment,
                });
              } catch (error) {
                // A comment failure must never mask the real checklist result.
                core.warning('failed to post checklist comment: ' + String((error && error.message) || error));
              }
            }

            core.setFailed(errors.join('\n'));

name: Reject documentation-only PRs

on:
  pull_request_target:
    types: [opened, reopened, edited, ready_for_review]

permissions:
  contents: read
  issues: write
  pull-requests: write

jobs:
  reject:
    name: Close documentation-only PRs
    runs-on: ubuntu-latest
    if: ${{ !github.event.pull_request.draft }}

    steps:
      - name: Auto-close documentation-only PRs
        uses: actions/github-script@v8
        with:
          script: |
            const pr = context.payload.pull_request;
            const title = (pr.title || '').trim();
            const body = pr.body || '';

            // 文档类型判定：标题以 docs: / docs( 开头，或 PR 描述勾选了「仅文档」。
            const isDocsTitle = /^docs\b/i.test(title) || /^docs\s*\(/i.test(title);
            const isDocsBoxed = /^-\s*\[[xX]\]\s*仅文档\s*$/m.test(body);
            if (!isDocsTitle && !isDocsBoxed) {
              console.log(`PR #${pr.number}: not documentation-only, keeping open.`);
              return;
            }

            // 仓库所有者维护文档 / 发布说明的 PR 不受此规则限制；
            // contributors 工作流（github-actions[bot]）的贡献者名单同步同样豁免。
            const isRepoOwner = pr.user.login === context.repo.owner || pr.user.login === 'github-actions[bot]';
            if (isRepoOwner) {
              console.log(`PR #${pr.number}: authored by repo owner or bot, keeping open.`);
              return;
            }
            // 拥有写权限的协作者（维护者）同样不受此限制，可直接提交任意改动。
            let hasWriteAccess = false;
            try {
              const perms = await github.rest.repos.getCollaboratorPermissionLevel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                username: pr.user.login,
              });
              hasWriteAccess = ['admin', 'write', 'maintain'].includes(perms.data.permission);
            } catch (error) {
              // 权限查询失败时保持打开（fail-open），避免误关维护者 / 协作者的 PR。
              hasWriteAccess = true;
              core.warning('collaborator permission lookup failed, keeping PR open: ' + String((error && error.message) || error));
            }
            if (hasWriteAccess) {
              console.log(`PR #${pr.number}: authored by write-access collaborator, keeping open.`);
              return;
            }

            const comment = [
              '本仓库不接受仅文档类 PR（标题以 `docs:` 开头或勾选了「仅文档」类型），此 PR 已被自动关闭。',
              '',
              '如需文档改动，请先到 [Issues](https://github.com/' + context.repo.owner + '/' + context.repo.repo + '/issues) 提 issue 讨论；',
              '若本 PR 实际包含代码改动，请把标题改为对应的 Conventional Commits 类型（`fix:` / `feat:` 等）后重新提交。',
            ].join('\n');

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: pr.number,
              body: comment,
            });
            await github.rest.issues.update({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: pr.number,
              state: 'closed',
              state_reason: 'not_planned',
            });

            core.setFailed(`PR #${pr.number} is documentation-only and was auto-closed.`);

name: Reject PRs outside the accepted content scope

on:
  pull_request_target:
    types: [opened, reopened, edited, ready_for_review]

permissions:
  contents: read
  issues: write
  pull-requests: write

jobs:
  reject:
    name: Close PRs outside the accepted content scope
    runs-on: ubuntu-latest
    if: ${{ !github.event.pull_request.draft }}

    steps:
      - name: Auto-close PRs outside the accepted content scope
        uses: actions/github-script@v8
        with:
          script: |
            const escapeRegExp = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const readSection = (label) => {
              const heading = escapeRegExp(label);
              const pattern = new RegExp(`(?:^|\\n)##\\s+${heading}\\s*\\n+([\\s\\S]*?)(?=\\n##\\s+|$)`, 'i');
              const match = body.match(pattern);
              return match ? match[1].replace(/<!--[\s\S]*?-->/g, '').trim() : '';
            };

            const isBlank = (value) => {
              const normalized = value.replace(/\s+/g, ' ').trim().toLowerCase();
              return normalized === '' || normalized === 'no response' || normalized === '_no response_';
            };

            // 勾选项按前缀识别：PR 模板可在稳定前缀后追加指向独立仓的说明文字。
            const hasCheckedPrefix = (value, label) => {
              const pattern = new RegExp(`^-\\s*\\[[xX]\\]\\s*${escapeRegExp(label)}`, 'm');
              return pattern.test(value);
            };
            const pr = context.payload.pull_request;
            const body = pr.body || '';

            const prCategory = readSection('PR 类别（PR Category）');
            const prType = readSection('PR 类型（PR Type）');

            // 本仓库不再接受任何外部内容贡献：四类内容贡献（皮肤、宠物、社区
            // 插件索引、agent 预设）都在各自的独立仓提交，由下方重定向分支处理。

            // 仅文档类 PR 由 reject-docs-pr.yml 处理，避免重复评论 / 关闭。
            const isDocsTitle = /^docs\b/i.test(pr.title || '') || /^docs\s*\(/i.test(pr.title || '');
            const isDocsBoxed = /^-\s*\[[xX]\]\s*仅文档\s*$/m.test(body);
            if (isDocsTitle || isDocsBoxed) {
              console.log('PR #' + pr.number + ': documentation-only, leaving to reject-docs-pr.yml.');
              return;
            }

            // 仓库所有者、机器人与拥有写权限的协作者（维护者）不受此规则限制。
            const isOwner = pr.user.login === context.repo.owner
              || pr.user.login === 'github-actions[bot]' || pr.user.type === 'Bot';
            if (isOwner) {
              console.log('PR #' + pr.number + ': authored by repository owner or bot, keeping open.');
              return;
            }
            let hasWriteAccess = false;
            try {
              const perms = await github.rest.repos.getCollaboratorPermissionLevel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                username: pr.user.login,
              });
              hasWriteAccess = ['admin', 'write', 'maintain'].includes(perms.data.permission);
            } catch (error) {
              // 权限查询失败时保持打开（fail-open），避免误关维护者 / 协作者的 PR。
              hasWriteAccess = true;
              core.warning('collaborator permission lookup failed, keeping PR open: ' + String((error && error.message) || error));
            }
            if (hasWriteAccess) {
              console.log('PR #' + pr.number + ': authored by write-access collaborator, keeping open.');
              return;
            }

            // 已迁出的内容贡献：皮肤、宠物与社区插件索引在各自的独立仓提交；
            // 本仓收到这类 PR 时关闭并重定向到对应仓库。
            const movedContribution = [
              {
                kind: '新皮肤收录',
                declared: hasCheckedPrefix(prCategory, '皮肤 / 皮肤中心') || hasCheckedPrefix(prType, '新皮肤收录'),
                target: '[dsh-skins](https://github.com/' + context.repo.owner + '/dsh-skins) 仓的 `skins/<id>/` 目录',
              },
              {
                kind: '新宠物收录',
                declared: hasCheckedPrefix(prType, '新宠物收录'),
                target: '[dsh-pet](https://github.com/' + context.repo.owner + '/dsh-pet) 仓的 `assets/<id>/` 目录',
              },
              {
                kind: '新预设收录',
                declared: hasCheckedPrefix(prType, '新预设收录'),
                target: '[dsh-presets](https://github.com/' + context.repo.owner + '/dsh-presets) 仓的 `presets/<id>/` 目录',
              },
              {
                kind: '社区插件索引登记',
                declared: hasCheckedPrefix(prCategory, '社区插件索引'),
                target: '[dsh-community-plugins](https://github.com/' + context.repo.owner + '/dsh-community-plugins) 仓的 `community.json`',
              },
            ].find((item) => item.declared);
            if (movedContribution) {
              const redirectComment = [
                '本仓库已不接收' + movedContribution.kind + '，本 PR 已自动关闭并重定向。',
                '',
                '请在 ' + movedContribution.target + ' 提交，并按对应独立仓的 PR 模板填写。',
              ].join('\n');
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: pr.number,
                body: redirectComment,
              });
              await github.rest.issues.update({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: pr.number,
                state: 'closed',
                state_reason: 'not_planned',
              });
              core.setFailed('PR #' + pr.number + ' declares ' + movedContribution.kind + ' and was auto-closed with a redirect.');
              return;
            }

            const comment = [
              '本仓库不接受外部直接提交的 PR，本 PR 已被自动关闭。',
              '',
              '内容贡献改在各自的独立仓提交：皮肤 / 皮肤中心 dsh-skins、宠物 dsh-pet、社区插件索引 dsh-community-plugins、agent 预设 dsh-presets。',
              '其余改动（bug 修复、功能增强、全新功能、文档、测试、维护等）请先到 [Issues](https://github.com/' + context.repo.owner + '/' + context.repo.repo + '/issues) 提 issue 讨论，确认后由维护者处理。',
            ].join('\n');

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: pr.number,
              body: comment,
            });
            await github.rest.issues.update({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: pr.number,
              state: 'closed',
              state_reason: 'not_planned',
            });

            core.setFailed('PR #' + pr.number + ' is outside the accepted content scope and was auto-closed.');

name: Reassign stale PR assignments

on:
  schedule:
    - cron: "30 3 * * *"
  workflow_dispatch:

permissions:
  contents: read
  issues: write
  pull-requests: write

jobs:
  sweep:
    name: Reassign stale PRs to the owner
    runs-on: ubuntu-latest
    timeout-minutes: 20

    steps:
      - name: Reassign PRs with an inactive assignee
        uses: actions/github-script@v8
        with:
          script: |
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const days = 14;
            const since = new Date(Date.now() - days * 86400000).toISOString();

            const assignees = new Set(['Aa728848']);
            try {
              const meta = await github.rest.repos.get({ owner, repo });
              const config = await github.rest.repos.getContent({
                owner,
                repo,
                path: '.github/pr-review-routes.json',
                ref: meta.data.default_branch,
              });
              const parsed = JSON.parse(
                Buffer.from(config.data.content, 'base64').toString('utf8')
              );
              for (const route of parsed.routes || []) {
                for (const user of route.assignees || []) {
                  assignees.add(user);
                }
              }
              for (const user of (parsed.defaultRoute || {}).assignees || []) {
                assignees.add(user);
              }
            } catch (error) {
              console.log(
                'routing config unavailable, defaulting to Aa728848'
              );
            }
            assignees.delete(owner);

            const items = [];
            for (const login of assignees) {
              const res = await github.rest.issues.listForRepo({
                owner,
                repo,
                state: 'open',
                assignee: login,
                per_page: 100,
              });
              items.push(...res.data);
              if (res.data.length === 100) {
                console.log('note: more than 100 open items for ' + login);
              }
            }
            if (items.length === 0) {
              console.log('no open assigned items, done.');
              return;
            }

            let reassigned = 0;
            for (const item of items) {
              const isPr = !!item.pull_request;
              // Issues remain with the collaborator; only stale PR work escalates.
              if (!isPr) {
                continue;
              }
              const login = item.assignee && item.assignee.login;
              if (!login || login === owner) {
                continue;
              }
              const number = item.number;

              let active = false;
              try {
                const comments = await github.rest.issues.listComments({
                  owner,
                  repo,
                  issue_number: number,
                  per_page: 100,
                });
                active = comments.data.some(
                  (comment) =>
                    comment.user &&
                    comment.user.login === login &&
                    new Date(comment.created_at) >= new Date(since)
                );
                if (!active && isPr) {
                  const reviews = await github.rest.pulls.listReviews({
                    owner,
                    repo,
                    pull_number: number,
                    per_page: 100,
                  });
                  active = reviews.data.some(
                    (review) =>
                      review.user &&
                      review.user.login === login &&
                      new Date(review.submitted_at || review.updated_at) >=
                        new Date(since)
                  );
                }
              } catch (error) {
                console.log(
                  'activity check failed for #' + number + ': ' + error.message
                );
              }

              if (active) {
                continue;
              }

              const kind = isPr ? 'PR' : 'Issue';
              try {
                const note = [
                  '维护者 @' + login + ' 已被分配但已超过 ' + days + ' 天未响应，',
                  '已自动转移给 @' + owner + ' 处理；如需仍由该维护者处理，可重新指派。',
                ].join('\n');
                await github.rest.issues.createComment({
                  owner,
                  repo,
                  issue_number: number,
                  body: note,
                });
                await github.rest.issues.addAssignees({
                  owner,
                  repo,
                  issue_number: number,
                  assignees: [owner],
                });
                await github.rest.issues.removeAssignees({
                  owner,
                  repo,
                  issue_number: number,
                  assignees: [login],
                });
                console.log(
                  kind + ' #' + number + ' reassigned from ' + login + ' to ' + owner + '.'
                );
                reassigned++;
              } catch (error) {
                console.log(
                  'reassign failed for #' + number + ': ' + error.message
                );
              }
            }
            console.log('total reassigned: ' + reassigned + '.');

